      var rr = el('div', 'runrow'), nb = el('button', 'btn', r.i < r.items.length - 1 ? 'Next question' : 'See results'); nb.type = 'button'; nb.id = 'q-next'; nb.addEventListener('click', nextQ); rr.appendChild(nb);
