      var tg = e.target && e.target.tagName; if (tg === 'SELECT' || tg === 'INPUT' || tg === 'TEXTAREA') return;
      if (e.key >= '1' && e.key <= '4') { e.preventDefault(); pick(+e.key - 1); }
