  return { curriculum: function (c) { curri = c; }, pre: function (m) { preMap = m; }, basics: function (b) { basics = { id: 'basics', name: BASIC, desc: b.desc, groups: b.groups, basic: true }; }, site: function (o) { Object.keys(o).forEach(function (k) { SITE[k] = o[k]; }); }, verify: function (v) { Object.keys(v).forEach(function (k) { verify[k] = v[k]; }); }, register: function (l) { lessons.push(l); }, tracks: function (t) { tracks = t; }, quiz: function (q) { quizBank = quizBank.concat(q); }, glossary: function (g) { gloss = gloss.concat(g); }, start: start, fmt: fmt, attach: attach };
