          P.box('o_addr2', 168, 132, 132, 70, { cls: 'wait', title: 'workAddress', sub: ['Address object', 'city Dallas', 'street Oak Ave'] }); P.arrow('ref2', 'o_member:b:0.754', 'o_addr2:t', { label: 'reference' });
