Lab.verify({ testing: ['run', '36 combinations were run, each in a new JVM, on Spring Boot 4.1.1, spring-test 7.0.9, JUnit Jupiter 6.0.3, and Mockito 5.23.0 and checked against the results'] });

Lab.verify({ thread: ['run', 'The 24 combinations were run on JDK 21 and checked against the results'] });

Lab.verify({ thread_basic: ['run', 'Compiled 6 combinations with javax.tools on JDK 21, ran each 20 times as a child java process, and checked the output and the number of newly started threads'] });

Lab.verify({ threadpool: ['run', 'Checked against the results of actually running a ThreadPoolExecutor'] });

Lab.verify({ tls: ['run', 'Checked by making real TLS 1.3 connections with openssl'] });

Lab.verify({ token_basic: ['run', 'Sent 10 combinations of tokens as real HTTP requests to an http server on Node.js 24.18.0 and checked against the results. The implementation that makes the tokens was checked against the example in RFC 7515 Appendix A.1 and the verification of the JWT library jose4j 0.9.5'] });

Lab.verify({ trace: ['doc', 'The W3C Trace Context standard and the OpenTelemetry documentation'] });

Lab.verify({ tx: ['run', 'All 12 combinations were run on SQLite with two connections'] });

Lab.verify({ tx_basic: ['run', 'Ran all 4 combinations with a real @Transactional proxy on Spring 7.0.9 and H2 2.4.240, and checked the row counts and the facts behind the step sentences'] });

Lab.verify({ txprop: ['run', '72 combinations were run on Spring 7.0.9 and H2 and checked against the results'] });

Lab.verify({ udp: ['part', 'Six of the eight combinations were run on 127.0.0.1 with the net and dgram modules of Node.js 24 and checked. The two combinations of TCP with a loss or a reordering are based on RFC 9293'] });

Lab.verify({ undoredo: ['doc', 'Checked against the MySQL documentation'] });

Lab.verify({ url: ['run', 'All 300 combinations were run and checked against Node.js 24 URL, URLSearchParams, and the HTTP client (received by a test server on 127.0.0.1)'] });

Lab.verify({ url_basic: ['run', 'Ran all 24 combinations on Node.js 24.18.0 and checked them (for the combinations without a port, it did not connect to port 80 and only intercepted where the client tried to connect)'] });

Lab.verify({ validation: ['run', 'Checked by sending requests for 48 combinations to a Spring Boot 4.1.1 server (Hibernate Validator 9.1.3)'] });

Lab.verify({ var_basic: ['run', 'Six combinations were compiled with javax.tools on JDK 21, run, and checked against the results'] });

Lab.verify({ vars: ['run', 'Checked by running 15 combinations on JDK 21'] });

Lab.verify({ viewproc: ['run', 'The same view, procedure, and trigger were created on MySQL 8.4, and orders for all 12 combinations were run and checked against the screen'] });

Lab.verify({ webattack: ['part', 'Part of each of the three attacks was checked with SQLite and a browser'] });

Lab.verify({ where_basic: ['run', 'Ran all 12 combinations on H2 2.4.240 and checked against the results, and checked the rules against the MySQL documentation'] });

Lab.verify({ windowfn: ['run', 'The SQL of all 24 combinations was run on MySQL 8.4, and the number of rows and the value added to each row were checked against the screen'] });

