Lab.curriculum([{"id":"java","name":"Java","desc":"From syntax to object-oriented programming, collections, threads, and the JVM. See what happens inside when code runs.","refs":["자바의 정석 3판 (in Korean)","Effective Java, 3rd Edition","Modern Java in Action","JVM 밑바닥까지 파헤치기 (Korean edition of a Chinese book)"],"groups":[{"name":"Basic syntax","items":[{"id":"vars"},{"id":"casting"},{"id":"loops"},{"id":"array"}]},{"name":"Classes and objects","items":[{"id":"ctor"},{"id":"static"},{"id":"inherit"},{"id":"poly"},{"id":"absint"},{"id":"access"},{"id":"inner"},{"id":"immut"},{"id":"strategy"}]},{"name":"Commonly used classes","items":[{"id":"eq"},{"id":"eqhash"},{"id":"strbuild"},{"id":"datetime"},{"id":"optional"}]},{"name":"Exceptions","items":[{"id":"exflow"},{"id":"chkex"}]},{"name":"Generics, enums, and annotations","items":[{"id":"generic"},{"id":"enumtype"},{"id":"annot"}]},{"name":"Collections","items":[{"id":"list"},{"id":"hashmap"},{"id":"setmap"},{"id":"sqh"},{"id":"cme"},{"id":"sorting"}]},{"name":"Lambdas and streams","items":[{"id":"lambda"},{"id":"stream"},{"id":"collect"},{"id":"parstream"}]},{"name":"Threads and concurrency","items":[{"id":"process"},{"id":"thread"},{"id":"race"},{"id":"deadlock"},{"id":"threadpool"},{"id":"ctx"},{"id":"parallel"},{"id":"blocking"}]},{"name":"JVM","items":[{"id":"stack"},{"id":"gc"},{"id":"jit"},{"id":"classload"}]},{"name":"I/O","items":[{"id":"iobuf"},{"id":"serial"}]}]},{"id":"spring","name":"Spring","desc":"The container and dependency injection, AOP and transactions, the path a web request takes, and what Spring Boot does for you.","refs":["토비의 스프링 3.1 (in Korean)","스프링 부트 핵심 가이드 (in Korean)","Inflearn Spring roadmap (order of a Korean online course)"],"groups":[{"name":"IoC container and DI","items":[{"id":"ioc"},{"id":"di"},{"id":"singleton"},{"id":"scope"},{"id":"lifecycle"}]},{"name":"AOP and proxies","items":[{"id":"proxy"},{"id":"aop"}]},{"name":"Data access and transactions","items":[{"id":"tx"},{"id":"txprop"},{"id":"jdbctmpl"},{"id":"connpool"}]},{"name":"Web MVC","items":[{"id":"servlet"},{"id":"mvc"},{"id":"binding"},{"id":"validation"},{"id":"msgconv"}]},{"name":"Spring Boot","items":[{"id":"autoconf"},{"id":"config"},{"id":"actuator"}]},{"name":"Other features","items":[{"id":"testing"},{"id":"restclient"},{"id":"cacheabs"},{"id":"security"}]}]},{"id":"jpa","name":"JPA","desc":"What it means to store objects in tables: the persistence context, relationships, lazy loading, and when and how many queries are sent.","refs":["자바 ORM 표준 JPA 프로그래밍 (in Korean)","Inflearn JPA roadmap (order of a Korean online course)","Hibernate ORM User Guide"],"groups":[{"name":"Getting started","items":[{"id":"ormwhy"}]},{"name":"Persistence context","items":[{"id":"pc"},{"id":"entitylife"},{"id":"merge"}]},{"name":"Entity mapping","items":[{"id":"mapping"},{"id":"embedded"}]},{"name":"Relationships","items":[{"id":"owner"},{"id":"relations"},{"id":"inheritmap"},{"id":"cascade"}]},{"name":"Proxies and fetching","items":[{"id":"lazyproxy"},{"id":"nplus1"}]},{"name":"Queries","items":[{"id":"fetchjoin"},{"id":"bulk"},{"id":"datajpa"},{"id":"dynquery"}]},{"name":"Web applications and performance","items":[{"id":"connpool"},{"id":"stock","t":"Optimistic and pessimistic locking"},{"id":"dtoquery"}]}]},{"id":"db","name":"Database","desc":"Table design and SQL, indexes and execution plans, transactions and locking, replication and distribution. See how data is stored and read.","refs":["Real MySQL 8.0 (in Korean)","SQL 레벨업 (Korean edition of a Japanese book)","데이터베이스 개론 (in Korean)","Designing Data-Intensive Applications"],"groups":[{"name":"Relational model and design","items":[{"id":"constraints"},{"id":"ermodel"},{"id":"normal"}]},{"name":"SQL","items":[{"id":"selectorder"},{"id":"join"},{"id":"subquery"},{"id":"windowfn"},{"id":"paging"},{"id":"viewproc"}]},{"name":"Indexes and execution plans","items":[{"id":"btree"},{"id":"index"},{"id":"compidx"},{"id":"explainplan"},{"id":"joinalgo"}]},{"name":"Transactions and locking","items":[{"id":"tx"},{"id":"iso"},{"id":"gaplock"},{"id":"stock"},{"id":"dbdeadlock"}]},{"name":"Storage and recovery","items":[{"id":"undoredo"},{"id":"bufferpool"}]},{"name":"Scaling and distribution","items":[{"id":"replica"},{"id":"shard"},{"id":"partition"},{"id":"redis","t":"Redis, a key-value store"},{"id":"nosql"}]}]},{"id":"network","name":"Networking","desc":"From typing an address to receiving the response: DNS, TCP, HTTP, TLS, and the machines in between.","refs":["성공과 실패를 결정하는 1%의 네트워크 원리 (Korean edition of a Japanese book)","HTTP: The Definitive Guide","모두의 네트워크 기초 (in Korean)","Computer Networking: A Top-Down Approach"],"groups":[{"name":"The big picture","items":[{"id":"journey"},{"id":"layers"}]},{"name":"Addresses and names","items":[{"id":"url"},{"id":"dns"},{"id":"subnet"},{"id":"routing"}]},{"name":"Transport layer","items":[{"id":"socket"},{"id":"tcp"},{"id":"udp"},{"id":"congestion"}]},{"name":"HTTP","items":[{"id":"httpmsg"},{"id":"httpver"},{"id":"cookie"},{"id":"etag"},{"id":"idem"},{"id":"redirect"},{"id":"conneg"},{"id":"cors"},{"id":"realtime"}]},{"name":"Secure connections","items":[{"id":"tls"}]},{"name":"In front of the web server","items":[{"id":"scale"},{"id":"revproxy"},{"id":"cdn"}]}]},{"id":"sec","name":"Security","desc":"Authentication (who you are), authorization (what you are allowed to do), web attacks and defenses, and cryptography.","refs":["OWASP Top 10:2025","Spring Security in Action","Web Security for Developers","RFC 6749 (OAuth 2.0)","RFC 7519 (JWT)"],"groups":[{"name":"Authentication","items":[{"id":"auth"},{"id":"cookie"},{"id":"pwhash"},{"id":"jwt"},{"id":"oauth"},{"id":"sessionfix"}]},{"name":"Authorization","items":[{"id":"security"},{"id":"accessctl"},{"id":"methodsec"}]},{"name":"Web attacks and defenses","items":[{"id":"webattack"},{"id":"cors"},{"id":"clickjack"},{"id":"infoleak"},{"id":"ratelimit"},{"id":"supplychain"}]},{"name":"Cryptography","items":[{"id":"crypto"},{"id":"tls"}]}]},{"id":"arch","name":"Architecture and operations","extra":true,"desc":"Topics for when traffic grows, when a system is split into services, and when you deploy and monitor it.","groups":[{"name":"High traffic","items":[{"id":"scale"},{"id":"cache"},{"id":"redis"},{"id":"ratelimit"}]},{"name":"Messaging and asynchronous processing","items":[{"id":"mq"},{"id":"kafka"}]},{"name":"Splitting into services","items":[{"id":"circuit"},{"id":"saga"},{"id":"gateway"}]},{"name":"Deployment and operations","items":[{"id":"cicd"},{"id":"deploy"},{"id":"container"},{"id":"k8s"}]},{"name":"Observability","items":[{"id":"pct"},{"id":"trace"}]},{"name":"Collaboration","items":[{"id":"git"}]}]}]);
Lab.basics({"desc":"Before looking at how a concept behaves in detail, these labs show what the concept looks like in code and what happens without it.","groups":[{"name":"Java","desc":"What you need to know first to read Java code.","items":[{"id":"var_basic"},{"id":"method_basic"},{"id":"class_basic"},{"id":"ref_basic"},{"id":"null_basic"},{"id":"ctor_basic"},{"id":"static_basic"},{"id":"inherit_basic"},{"id":"interface_basic"},{"id":"exception_basic"},{"id":"generic_basic"},{"id":"collection_basic"},{"id":"lambda_basic"},{"id":"stream_basic"},{"id":"annot_basic"},{"id":"thread_basic"},{"id":"lock_basic"},{"id":"pool_basic"},{"id":"jvm_basic"},{"id":"io_basic"},{"id":"dep_basic"}]},{"name":"Spring","desc":"What lies underneath when Spring handles a web request.","items":[{"id":"bean_basic"},{"id":"di_basic"},{"id":"aop_basic"},{"id":"servlet_basic"},{"id":"controller_basic"},{"id":"config_basic"},{"id":"jdbc_basic"},{"id":"tx_basic"},{"id":"boot_basic"},{"id":"test_basic"}]},{"name":"JPA","desc":"What comes up when Java objects are stored in tables.","items":[{"id":"entity_basic"},{"id":"pc_basic"},{"id":"repo_basic"},{"id":"relation_basic"},{"id":"lazy_basic"},{"id":"jpql_basic"}]},{"name":"Database","desc":"The basic rules for putting data into tables and finding it again.","items":[{"id":"table_basic"},{"id":"pk_basic"},{"id":"fk_basic"},{"id":"where_basic"},{"id":"join_basic"},{"id":"groupby_basic"},{"id":"index_basic"},{"id":"dbtx_basic"},{"id":"dblock_basic"},{"id":"durable_basic"}]},{"name":"Networking","desc":"What the messages between a browser and a server look like.","items":[{"id":"port_basic"},{"id":"tcp_basic"},{"id":"url_basic"},{"id":"dns_basic"},{"id":"http_basic"},{"id":"httpmethod_basic"},{"id":"httpres_basic"},{"id":"cookie_basic"},{"id":"json_basic"},{"id":"https_basic"},{"id":"proxy_basic"}]},{"name":"Security","desc":"The basics of checking who someone is and keeping data safe.","items":[{"id":"authn_basic"},{"id":"session_basic"},{"id":"token_basic"},{"id":"hash_basic"},{"id":"crypto_basic"},{"id":"origin_basic"},{"id":"injection_basic"}]},{"name":"Architecture and operations","desc":"What comes up when you run several server programs together.","items":[{"id":"process_basic"},{"id":"remote_basic"},{"id":"lb_basic"},{"id":"cache_basic"},{"id":"queue_basic"},{"id":"deploy_basic"},{"id":"git_basic"}]}]});
